<?php

namespace Tests\Feature;

use App\Enums\ListingStatus;
use App\Enums\PropertyType;
use App\Listeners\CreateAlertsForMatchingSearches;
use App\Models\Alert;
use App\Models\Branch;
use App\Models\Listing;
use App\Models\SavedSearch;
use App\Models\User;
use Illuminate\Events\CallQueuedListener;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\Queue;
use PHPUnit\Framework\Attributes\DataProvider;
use Tests\TestCase;

/**
 * Alerts are generated by a queued listener; the test environment runs the
 * queue synchronously, so they exist as soon as the listing is saved.
 */
class ListingAlertTest extends TestCase
{
    use RefreshDatabase;

    private User $user;

    private Branch $leeds;

    protected function setUp(): void
    {
        parent::setUp();

        $this->user = User::factory()->create();
        $this->leeds = Branch::factory()->create(['region' => 'Leeds']);
    }

    /**
     * A 3-bed flat in Leeds at £250k, as a draft ready to be published.
     *
     * @param  array<string, mixed>  $attributes
     */
    private function draftListing(array $attributes = []): Listing
    {
        return Listing::factory()->draft()->for($this->leeds)->create([
            'price' => 250_000,
            'bedrooms' => 3,
            'property_type' => PropertyType::Flat,
            ...$attributes,
        ]);
    }

    /**
     * @param  array<string, mixed>  $criteria
     */
    private function search(array $criteria = [], ?User $user = null): SavedSearch
    {
        return SavedSearch::factory()->for($user ?? $this->user)->create([
            'max_price' => null,
            'min_bedrooms' => null,
            'property_type' => null,
            'region' => null,
            ...$criteria,
        ]);
    }

    private function goLive(Listing $listing): void
    {
        $listing->update(['status' => ListingStatus::Live, 'listed_at' => now()]);
    }

    public function test_publishing_a_matching_listing_alerts_the_user(): void
    {
        $search = $this->search([
            'max_price' => 300_000,
            'min_bedrooms' => 2,
            'property_type' => PropertyType::Flat,
            'region' => 'Leeds',
        ]);
        $listing = $this->draftListing();

        $this->assertDatabaseCount('alerts', 0);

        $this->goLive($listing);

        $alert = $this->user->alerts()->sole();
        $this->assertSame($listing->id, $alert->listing_id);
        $this->assertSame($search->id, $alert->saved_search_id);
        $this->assertNull($alert->read_at);
    }

    public function test_the_alert_job_is_dropped_if_the_listing_is_deleted_before_it_runs(): void
    {
        Queue::fake();

        $this->goLive($this->draftListing());

        Queue::assertPushed(
            CallQueuedListener::class,
            fn (CallQueuedListener $job) => $job->class === CreateAlertsForMatchingSearches::class
                && $job->deleteWhenMissingModels === true,
        );
    }

    public function test_a_listing_created_live_alerts_matching_users(): void
    {
        $this->search(['region' => 'Leeds']);

        $listing = Listing::factory()->live()->for($this->leeds)->create();

        $this->assertSame([$listing->id], $this->user->alerts()->pluck('listing_id')->all());
    }

    /**
     * @return array<string, array{array<string, mixed>}>
     */
    public static function nonMatchingCriteria(): array
    {
        return [
            'price above max' => [['max_price' => 249_999]],
            'too few bedrooms' => [['min_bedrooms' => 4]],
            'other property type' => [['property_type' => PropertyType::Detached]],
            'other region' => [['region' => 'Bristol']],
        ];
    }

    /**
     * @param  array<string, mixed>  $criteria
     */
    #[DataProvider('nonMatchingCriteria')]
    public function test_a_listing_failing_any_criterion_does_not_alert(array $criteria): void
    {
        $this->search($criteria);

        $this->goLive($this->draftListing());

        $this->assertDatabaseCount('alerts', 0);
    }

    public function test_limits_are_inclusive(): void
    {
        $this->search(['max_price' => 250_000, 'min_bedrooms' => 3]);

        $this->goLive($this->draftListing());

        $this->assertSame(1, $this->user->alerts()->count());
    }

    public function test_a_search_with_no_criteria_set_matches_anything(): void
    {
        $this->search();

        $this->goLive($this->draftListing());

        $this->assertSame(1, $this->user->alerts()->count());
    }

    public function test_several_matching_searches_give_a_user_one_alert(): void
    {
        $first = $this->search(['region' => 'Leeds']);
        $this->search(['property_type' => PropertyType::Flat]);

        $this->goLive($this->draftListing());

        $this->assertSame($first->id, $this->user->alerts()->sole()->saved_search_id);
    }

    public function test_each_matching_user_gets_their_own_alert(): void
    {
        $other = User::factory()->create();
        $this->search(['region' => 'Leeds']);
        $this->search(['region' => 'Leeds'], $other);
        $this->search(['region' => 'Bristol'], User::factory()->create());

        $this->goLive($this->draftListing());

        $this->assertEqualsCanonicalizing(
            [$this->user->id, $other->id],
            Alert::query()->pluck('user_id')->all(),
        );
    }

    public function test_editing_a_live_listing_does_not_alert_again(): void
    {
        $listing = $this->draftListing();
        $this->goLive($listing);
        $this->search();

        $listing->update(['price' => 240_000]);

        $this->assertDatabaseCount('alerts', 0);
    }

    public function test_coming_back_on_the_market_alerts_new_matches_but_not_the_already_alerted(): void
    {
        $this->search();
        $listing = $this->draftListing();
        $this->goLive($listing);

        $listing->update(['status' => ListingStatus::UnderOffer]);
        $latecomer = User::factory()->create();
        $this->search([], $latecomer);
        $this->goLive($listing);

        $this->assertSame(1, $this->user->alerts()->count());
        $this->assertSame(1, $latecomer->alerts()->count());
    }

    /**
     * @return array<string, array{ListingStatus}>
     */
    public static function offMarketStatuses(): array
    {
        return [
            'draft' => [ListingStatus::Draft],
            'under offer' => [ListingStatus::UnderOffer],
            'sold' => [ListingStatus::Sold],
        ];
    }

    #[DataProvider('offMarketStatuses')]
    public function test_moving_to_a_non_live_status_does_not_alert(ListingStatus $status): void
    {
        $this->search();
        $listing = Listing::factory()->live()->for($this->leeds)->create();
        Alert::query()->delete();

        $listing->update(['status' => $status]);

        $this->assertDatabaseCount('alerts', 0);
    }

    /**
     * Deliberate: a new search only alerts about listings that go live after it
     * is saved. What's already on the market is on the results page.
     */
    public function test_saving_a_search_does_not_alert_on_listings_already_live(): void
    {
        Listing::factory()->live()->for($this->leeds)->create();

        $this->actingAs($this->user)->post('/saved-searches', ['region' => 'Leeds']);

        $this->assertSame(1, $this->user->savedSearches()->count());
        $this->assertDatabaseCount('alerts', 0);
    }

    public function test_deleting_the_search_keeps_the_alert(): void
    {
        $search = $this->search();
        $this->goLive($this->draftListing());

        $search->delete();

        $this->assertNull($this->user->alerts()->sole()->saved_search_id);
    }

    /**
     * Alerting asks "which searches match this listing?" while the results page
     * asks "which listings match this search?". The two are separate queries,
     * so check they agree over a spread of searches and listings.
     */
    public function test_reverse_matching_agrees_with_the_listings_filter(): void
    {
        $bristol = Branch::factory()->create(['region' => 'Bristol']);

        $searches = collect([
            [],
            ['max_price' => 250_000],
            ['max_price' => 249_999],
            ['min_bedrooms' => 3],
            ['min_bedrooms' => 4],
            ['property_type' => PropertyType::Flat],
            ['property_type' => PropertyType::Detached],
            ['region' => 'Leeds'],
            ['region' => 'Bristol'],
            ['max_price' => 400_000, 'min_bedrooms' => 2, 'property_type' => PropertyType::Flat, 'region' => 'Leeds'],
        ])->map(fn (array $criteria) => $this->search($criteria));

        $listings = collect([
            ['branch_id' => $this->leeds->id, 'price' => 250_000, 'bedrooms' => 3, 'property_type' => PropertyType::Flat],
            ['branch_id' => $this->leeds->id, 'price' => 500_000, 'bedrooms' => 5, 'property_type' => PropertyType::Detached],
            ['branch_id' => $bristol->id, 'price' => 150_000, 'bedrooms' => 1, 'property_type' => PropertyType::Flat],
            ['branch_id' => $bristol->id, 'price' => 249_999, 'bedrooms' => 4, 'property_type' => PropertyType::Terraced],
        ])->map(fn (array $attributes) => Listing::factory()->live()->create($attributes));

        foreach ($listings as $listing) {
            $expected = $searches
                ->filter(fn (SavedSearch $search) => Listing::query()
                    ->matching($search->criteria())
                    ->whereKey($listing->id)
                    ->exists())
                ->pluck('id')
                ->sort()
                ->values()
                ->all();

            $actual = SavedSearch::query()
                ->matchingListing($listing)
                ->orderBy('id')
                ->pluck('id')
                ->all();

            $this->assertSame($expected, $actual, "Mismatch for listing {$listing->reference}");
        }
    }

    public function test_publish_command_makes_a_listing_live_and_alerts(): void
    {
        $this->search(['region' => 'Leeds']);
        $listing = $this->draftListing();

        $this->artisan('listings:publish', ['reference' => $listing->reference])
            ->assertSuccessful();

        $this->assertSame(ListingStatus::Live, $listing->fresh()?->status);
        $this->assertSame(1, $this->user->alerts()->count());
    }

    public function test_publish_command_fails_for_an_unknown_reference(): void
    {
        $this->artisan('listings:publish', ['reference' => 'STR-NOPE'])
            ->assertFailed();
    }

    public function test_draft_command_creates_a_draft_listing(): void
    {
        $this->search();

        $this->artisan('listings:draft')->assertSuccessful();

        $listing = Listing::query()->sole();
        $this->assertSame(ListingStatus::Draft, $listing->status);
        $this->assertSame($this->leeds->id, $listing->branch_id);
        $this->assertDatabaseCount('branches', 1);
        $this->assertDatabaseCount('alerts', 0);
    }

    public function test_draft_command_fails_when_there_are_no_branches(): void
    {
        $this->leeds->delete();

        $this->artisan('listings:draft')->assertFailed();

        $this->assertDatabaseCount('listings', 0);
    }

    /**
     * The manual testing loop, end to end.
     */
    public function test_drafting_then_publishing_alerts_a_matching_search(): void
    {
        $this->search();

        $this->artisan('listings:draft')->assertSuccessful();
        $reference = Listing::query()->sole()->reference;

        $this->artisan('listings:publish', ['reference' => $reference])->assertSuccessful();

        $this->assertSame(1, $this->user->alerts()->count());
    }
}
